export type SpanPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function spanProgram() {
  return <T extends SpanPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { span: SpanPlugin }> => {
    return extendClient(client, {
      span: <SpanPlugin>{
        accounts: {
          candle: addSelfFetchFunctions(client, getCandleCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          ticket: addSelfFetchFunctions(client, getTicketCodec()),
        },
        instructions: {
          buy: (input) =>
            addSelfPlanAndSendFunctions(client, getBuyInstructionAsync(input)),
          init: (input) =>
            addSelfPlanAndSendFunctions(client, getInitInstructionAsync(input)),
          loadSpan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLoadSpanInstructionAsync(input),
            ),
          mark: (input) =>
            addSelfPlanAndSendFunctions(client, getMarkInstructionAsync(input)),
          openCandle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenCandleInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          openTicket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenTicketInstructionAsync(input),
            ),
          read: (input) =>
            addSelfPlanAndSendFunctions(client, getReadInstructionAsync(input)),
          setFeed: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetFeedInstructionAsync(input),
            ),
          setParams: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetParamsInstructionAsync(input),
            ),
          setSpan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetSpanInstructionAsync(input),
            ),
          settle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          vault: findVaultPda,
          candle: findCandlePda,
          ticket: findTicketPda,
        },
        identifyAccount: identifySpanAccount,
        identifyInstruction: identifySpanInstruction,
        parseInstruction: parseSpanInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
